INSERT INTO esifit."Author" (id,name,bio,"avatarEmoji","credentialLabel") VALUES ('esifit-editorial','تحریریه اسی‌فیت','راهنمای عمومی و آموزش استفاده از محصول؛ با ارجاع به منابع اصلی.','✍️','') ON CONFLICT (id) DO NOTHING;
INSERT INTO esifit."Category" (id,slug,"nameFa",description,"orderIndex") SELECT 'editorial_c_'||md5(x->>'slug'),x->>'slug',x->>'nameFa',x->>'description',(x->>'orderIndex')::int FROM jsonb_array_elements('[{"slug": "training", "nameFa": "تمرین", "description": "برنامه‌ریزی، ثبت تمرین و شروع قدم‌به‌قدم", "orderIndex": 1}, {"slug": "nutrition", "nameFa": "تغذیه", "description": "انتخاب غذا، سهم‌ها و ثبت تغذیه", "orderIndex": 2}, {"slug": "recovery", "nameFa": "ریکاوری", "description": "خواب، استراحت و پیوستگی برنامه", "orderIndex": 3}, {"slug": "science", "nameFa": "علم و پژوهش", "description": "شناخت کاربرد و محدودیت عددها", "orderIndex": 4}, {"slug": "stories", "nameFa": "تجربه کاربران", "description": "داستان‌های واقعی کاربران؛ به‌زودی", "orderIndex": 5}]'::jsonb) x ON CONFLICT (slug) DO NOTHING;
INSERT INTO esifit."Article" ("id","slug","title","contentType","status","authorId","categoryId","metaTitle","metaDescription","excerpt","coverEmoji","readingMinutes","contentBlocks","calculatorSlug","publishedAt","updatedAt","revision","revisionNote") VALUES ('editorial_a_57d057aa502fea406068fcfb70351972','start-small-training-week','هفته اول تمرین؛ کوچک شروع کن، منظم ادامه بده','guide','published','esifit-editorial',(SELECT id FROM esifit."Category" WHERE slug='training'),'هفته اول تمرین؛ کوچک شروع کن، منظم ادامه بده','شروع خوب، سنگین‌ترین برنامه نیست؛ برنامه‌ای است که بتوانی هفته بعد هم انجامش بدهی. هدف هفته اول را آشناشدن با حرکت‌ها و پیدا کردن زمان مناسب تمرین بگذ','شروع خوب، سنگین‌ترین برنامه نیست؛ برنامه‌ای است که بتوانی هفته بعد هم انجامش بدهی. هدف هفته اول را آشناشدن با حرکت‌ها و پیدا کردن زمان مناسب تمرین بگذار.','🏋️',1,'[{"type": "p", "text": "شروع خوب، سنگین‌ترین برنامه نیست؛ برنامه‌ای است که بتوانی هفته بعد هم انجامش بدهی. هدف هفته اول را آشناشدن با حرکت‌ها و پیدا کردن زمان مناسب تمرین بگذار."}, {"type": "h2", "text": "برنامه‌ای انتخاب کن که در تقویمت جا شود"}, {"type": "p", "text": "در اسی‌فیت تعداد جلسات را با زمان واقعی و وسایلی که داری هماهنگ کن. برنامه خانه و دمبل برای همین تفاوت‌هاست. اگر با مربی کار می‌کنی، تجربه و محدودیت وسایل را در پرونده‌ات دقیق ثبت کن تا انتخاب حرکت‌ها معنی‌دار باشد."}, {"type": "h2", "text": "جلسه اول را قابل مقایسه ثبت کن"}, {"type": "list", "items": ["نام حرکت، وزنه و تکرار واقعی را بنویس؛ عدد هدف با نتیجه انجام‌شده فرق دارد.", "قبل از افزایش وزنه، اجرای حرکت را یاد بگیر و از مربی بازخورد بگیر.", "همه روزهای خالی تقویم را با تمرین پُر نکن؛ روز استراحت بخشی از برنامه است."]}, {"type": "h2", "text": "چه چیزی را موفقیت حساب کنیم؟"}, {"type": "p", "text": "انجام جلسات برنامه‌ریزی‌شده و ثبت صادقانه نتیجه، برای شروع معیار بهتری از مقایسه وزنه با دیگران است. توصیه عمومی WHO هم بر فعال‌بودن منظم و شروع تدریجی تأکید دارد؛ شدت مناسب هر فرد باید جداگانه تنظیم شود."}]',NULL,now(),now(),1,'انتشار اولیه') ON CONFLICT (slug) DO NOTHING;
INSERT INTO esifit."ArticleSource" (id,"articleId",title,publisher,url,"sourceType") VALUES ('editorial_s_73ee6f9bee98b91767feb237f65c41a9',(SELECT id FROM esifit."Article" WHERE slug='start-small-training-week'),'فعالیت بدنی و توصیه‌های عمومی','سازمان جهانی بهداشت','https://www.who.int/news-room/fact-sheets/detail/physical-activity','organization') ON CONFLICT (id) DO NOTHING;
INSERT INTO esifit."Article" ("id","slug","title","contentType","status","authorId","categoryId","metaTitle","metaDescription","excerpt","coverEmoji","readingMinutes","contentBlocks","calculatorSlug","publishedAt","updatedAt","revision","revisionNote") VALUES ('editorial_a_b0a3e72d34c9478d165ad0db8a547c26','workout-log-that-helps','چطور دفتر تمرین بنویسیم که به درد پیشرفت بخورد؟','guide','published','esifit-editorial',(SELECT id FROM esifit."Category" WHERE slug='training'),'چطور دفتر تمرین بنویسیم که به درد پیشرفت بخورد؟','دفتر تمرین وقتی مفید است که جلسه بعد بتوانی از آن تصمیم بگیری؛ تعداد زیاد عدد به‌تنهایی کمکی نمی‌کند. چند داده ثابت و قابل مقایسه کافی است.','دفتر تمرین وقتی مفید است که جلسه بعد بتوانی از آن تصمیم بگیری؛ تعداد زیاد عدد به‌تنهایی کمکی نمی‌کند. چند داده ثابت و قابل مقایسه کافی است.','📝',1,'[{"type": "p", "text": "دفتر تمرین وقتی مفید است که جلسه بعد بتوانی از آن تصمیم بگیری؛ تعداد زیاد عدد به‌تنهایی کمکی نمی‌کند. چند داده ثابت و قابل مقایسه کافی است."}, {"type": "h2", "text": "چه چیزهایی را ثبت کنیم؟"}, {"type": "list", "items": ["حرکت و وسیله را دقیق انتخاب کن؛ پرس دمبل با پرس دستگاه یک رکورد واحد نیست.", "وزنه و تکرار انجام‌شده را برای هر ست وارد کن.", "اگر حرکت جایگزین شد، نتیجه را با همان حرکت جدید ثبت کن.", "جلسه را پس از پایان ثبت نهایی کن تا در تاریخچه دیده شود."]}, {"type": "h2", "text": "یک مثال ساده"}, {"type": "p", "text": "اگر هفته قبل یک حرکت را با وزنه مشخص و تکرارهای کمتر از هدف انجام داده‌ای، همان عدد به مربی کمک می‌کند برنامه بعدی را تنظیم کند. زیادکردن هم‌زمان ست، وزنه و تکرار، مقایسه را سخت می‌کند. اجرای کنترل‌شده و برنامه مناسب مهم‌تر از زیباتر شدن نمودار است."}, {"type": "h2", "text": "هر نتیجه‌ای رکورد نیست"}, {"type": "p", "text": "یک جلسه سبک یا ناقص هم داده واقعی است. برای خوش‌رنگ شدن گزارش عددها را اصلاح نکن. هدف دفتر تمرین ساختن سابقه قابل اعتماد است؛ مربی می‌تواند تصمیم افزایش یا کاهش فشار را بر اساس این سابقه و شرایطت بگیرد."}]',NULL,now(),now(),1,'انتشار اولیه') ON CONFLICT (slug) DO NOTHING;
INSERT INTO esifit."ArticleSource" (id,"articleId",title,publisher,url,"sourceType") VALUES ('editorial_s_82c0fe3394303d9668b98211c2bca42b',(SELECT id FROM esifit."Article" WHERE slug='workout-log-that-helps'),'فعالیت بدنی و توصیه‌های عمومی','سازمان جهانی بهداشت','https://www.who.int/news-room/fact-sheets/detail/physical-activity','organization') ON CONFLICT (id) DO NOTHING;
INSERT INTO esifit."Article" ("id","slug","title","contentType","status","authorId","categoryId","metaTitle","metaDescription","excerpt","coverEmoji","readingMinutes","contentBlocks","calculatorSlug","publishedAt","updatedAt","revision","revisionNote") VALUES ('editorial_a_58142764cd6e8835d86cfa7062af9279','balanced-plate-everyday','بشقاب روزمره را متعادل‌تر بچینیم','guide','published','esifit-editorial',(SELECT id FROM esifit."Category" WHERE slug='nutrition'),'بشقاب روزمره را متعادل‌تر بچینیم','برای بهتر غذاخوردن لازم نیست هر وعده پیچیده یا گران باشد. ترکیب متنوع مواد غذایی و توجه به مقدار مصرف، از دنبال‌کردن یک غذای معجزه‌آسا کاربردی‌تر است.','برای بهتر غذاخوردن لازم نیست هر وعده پیچیده یا گران باشد. ترکیب متنوع مواد غذایی و توجه به مقدار مصرف، از دنبال‌کردن یک غذای معجزه‌آسا کاربردی‌تر است.','🥗',1,'[{"type": "p", "text": "برای بهتر غذاخوردن لازم نیست هر وعده پیچیده یا گران باشد. ترکیب متنوع مواد غذایی و توجه به مقدار مصرف، از دنبال‌کردن یک غذای معجزه‌آسا کاربردی‌تر است."}, {"type": "h2", "text": "یک الگوی ساده برای ترکیب بشقاب"}, {"type": "p", "text": "راهنمای غذایی کانادا پیشنهاد می‌کند حدود نیمی از بشقاب را سبزی و میوه، یک‌چهارم را غلات کامل و یک‌چهارم را منابع پروتئین تشکیل دهند. این نسبت، راهنمای ترکیب است؛ مقدار دقیق انرژی را برای همه یکسان تعیین نمی‌کند."}, {"type": "h2", "text": "با غذاهای آشنا اجرا کن"}, {"type": "list", "items": ["کنار برنج و مرغ، سهم سبزیجات یا سالاد را هم ببین.", "گاهی حبوبات را به‌عنوان یکی از منابع پروتئین انتخاب کن.", "روغن، سس و نوشیدنی همراه غذا را هم در ثبت وعده فراموش نکن."]}, {"type": "h2", "text": "از بشقاب تا ثبت روزانه"}, {"type": "p", "text": "در دفتر تغذیه اسی‌فیت نام غذا و مقدار هر سهم را بررسی کن. لازم نیست همه وعده‌ها شبیه هم باشند؛ مرور چند روز به تو نشان می‌دهد چه چیزهایی در الگوی همیشگی‌ات جا می‌مانند. این راهنما نسخه رژیم‌درمانی شخصی نیست."}]',NULL,now(),now(),1,'انتشار اولیه') ON CONFLICT (slug) DO NOTHING;
INSERT INTO esifit."ArticleSource" (id,"articleId",title,publisher,url,"sourceType") VALUES ('editorial_s_a3fdf460de618a0e2446028f42a47172',(SELECT id FROM esifit."Article" WHERE slug='balanced-plate-everyday'),'راهنمای بشقاب غذایی','Health Canada','https://www.canada.ca/en/health-canada/services/food-guide/eating-support/cooking/make-healthy-meals-plate.html','organization') ON CONFLICT (id) DO NOTHING;
INSERT INTO esifit."Article" ("id","slug","title","contentType","status","authorId","categoryId","metaTitle","metaDescription","excerpt","coverEmoji","readingMinutes","contentBlocks","calculatorSlug","publishedAt","updatedAt","revision","revisionNote") VALUES ('editorial_a_6f9c6b0cb73761ed612f08128a56cd61','food-portions-raw-cooked','خام، پخته یا یک سهم؟ غذایت را درست ثبت کن','guide','published','esifit-editorial',(SELECT id FROM esifit."Category" WHERE slug='nutrition'),'خام، پخته یا یک سهم؟ غذایت را درست ثبت کن','دو ردیف با نام مشابه ممکن است کالری متفاوتی داشته باشند؛ اول مقدار سهم و حالت خام یا پخته را بخوان. بیشتر خطاهای ثبت غذا از همین تفاوت‌ها شروع می‌شود.','دو ردیف با نام مشابه ممکن است کالری متفاوتی داشته باشند؛ اول مقدار سهم و حالت خام یا پخته را بخوان. بیشتر خطاهای ثبت غذا از همین تفاوت‌ها شروع می‌شود.','⚖️',1,'[{"type": "p", "text": "دو ردیف با نام مشابه ممکن است کالری متفاوتی داشته باشند؛ اول مقدار سهم و حالت خام یا پخته را بخوان. بیشتر خطاهای ثبت غذا از همین تفاوت‌ها شروع می‌شود."}, {"type": "h2", "text": "عدد بدون واحد کافی نیست"}, {"type": "p", "text": "در کتابخانه اسی‌فیت مقدار غذا کنار سهم نوشته شده است. مثلاً سهم روغن زیتون ۱۰ گرم است، ولی بسیاری از غذاها بر پایه ۱۰۰ گرم ثبت شده‌اند. انتخاب دو سهم از یک ردیف، یعنی دو برابر همان مقدار اعلام‌شده؛ نه دو قاشق یا دو بشقاب نامشخص."}, {"type": "h2", "text": "حالت غذا باید با اندازه‌گیری تو یکی باشد"}, {"type": "list", "items": ["برای غذایی که پس از پخت وزن کرده‌ای، ردیف پخته را انتخاب کن.", "وزن برنج خام را با مشخصات برنج پخته ترکیب نکن.", "برای غذای چندجزئی، روغن و افزودنی‌ها در نتیجه اثر دارند."]}, {"type": "h2", "text": "برچسب منبع چه می‌گوید؟"}, {"type": "p", "text": "ردیف‌های USDA به رکورد غذایی و سهم مشخص ارجاع می‌دهند. غذاهای ترکیبی ایرانی با برچسب تقریبی مشخص‌اند، چون دستور پخت خانه‌ها یکسان نیست. برای ثبت قابل مقایسه، روش انتخاب غذا و اندازه‌گیری را در روزهای مختلف ثابت نگه دار؛ عدد نمایش‌داده‌شده اندازه‌گیری آزمایشگاهی غذای بشقاب تو نیست."}]',NULL,now(),now(),1,'انتشار اولیه') ON CONFLICT (slug) DO NOTHING;
INSERT INTO esifit."ArticleSource" (id,"articleId",title,publisher,url,"sourceType") VALUES ('editorial_s_5c1215406493f67b5ce83f5d497c75eb',(SELECT id FROM esifit."Article" WHERE slug='food-portions-raw-cooked'),'FoodData Central: راهنمای داده‌های غذایی','USDA','https://fdc.nal.usda.gov/data-documentation.html','organization') ON CONFLICT (id) DO NOTHING;
INSERT INTO esifit."Article" ("id","slug","title","contentType","status","authorId","categoryId","metaTitle","metaDescription","excerpt","coverEmoji","readingMinutes","contentBlocks","calculatorSlug","publishedAt","updatedAt","revision","revisionNote") VALUES ('editorial_a_432bcd3a9080fe964a561857f5ec1d03','sleep-before-more-training','قبل از یک تمرین بیشتر، خواب را بررسی کن','guide','published','esifit-editorial',(SELECT id FROM esifit."Category" WHERE slug='recovery'),'قبل از یک تمرین بیشتر، خواب را بررسی کن','برنامه تمرین فقط ساعت حضور در باشگاه نیست. زمان خواب و استراحت هم در برنامه روزانه‌ات جا می‌گیرند؛ ثبت آن‌ها کمک می‌کند شرایط روزهای مختلف را بهتر به ','برنامه تمرین فقط ساعت حضور در باشگاه نیست. زمان خواب و استراحت هم در برنامه روزانه‌ات جا می‌گیرند؛ ثبت آن‌ها کمک می‌کند شرایط روزهای مختلف را بهتر به یاد بیاوری.','🌙',1,'[{"type": "p", "text": "برنامه تمرین فقط ساعت حضور در باشگاه نیست. زمان خواب و استراحت هم در برنامه روزانه‌ات جا می‌گیرند؛ ثبت آن‌ها کمک می‌کند شرایط روزهای مختلف را بهتر به یاد بیاوری."}, {"type": "h2", "text": "مدت و کیفیت هر دو مهم‌اند"}, {"type": "p", "text": "CDC برای بزرگسالان ۱۸ تا ۶۰ سال، دست‌کم ۷ ساعت خواب در شب را توصیه می‌کند. بیداری‌های مکرر و احساس سرحال‌نبودن هم مهم‌اند؛ صرفاً تعداد ساعت را معیار نگذار."}, {"type": "h2", "text": "از یک عادت کوچک شروع کن"}, {"type": "list", "items": ["زمان خواب و بیداری را تا حد ممکن منظم نگه دار.", "اتاق خواب را آرام و مناسب استراحت آماده کن.", "مصرف کافئین عصر و شب را بررسی کن.", "دستگاه‌های الکترونیکی را پیش از خواب کنار بگذار."]}, {"type": "h2", "text": "عدد آمادگی را چطور بخوانیم؟"}, {"type": "p", "text": "امتیازهای داخل اپ را راهنمای مرور داده‌های ثبت‌شده بدان، نه تشخیص پزشکی یا دستور قطعی برای تمرین سنگین. اگر خواب نامناسب ادامه پیدا کرده است یا در طول روز خواب‌آلودگی آزاردهنده داری، علت را با پزشک بررسی کن؛ افزودن مکمل یا جلسه تمرین، جای این بررسی را نمی‌گیرد."}]',NULL,now(),now(),1,'انتشار اولیه') ON CONFLICT (slug) DO NOTHING;
INSERT INTO esifit."ArticleSource" (id,"articleId",title,publisher,url,"sourceType") VALUES ('editorial_s_c988a9dae5ee5003e193fa64dcd1c4fc',(SELECT id FROM esifit."Article" WHERE slug='sleep-before-more-training'),'درباره خواب و عادت‌های خواب','CDC','https://www.cdc.gov/sleep/about/index.html','organization') ON CONFLICT (id) DO NOTHING;
INSERT INTO esifit."Article" ("id","slug","title","contentType","status","authorId","categoryId","metaTitle","metaDescription","excerpt","coverEmoji","readingMinutes","contentBlocks","calculatorSlug","publishedAt","updatedAt","revision","revisionNote") VALUES ('editorial_a_383b0b2c5316c92f1c5c6d453e832caf','rest-day-without-guilt','روز استراحت هم بخشی از برنامه است','guide','published','esifit-editorial',(SELECT id FROM esifit."Category" WHERE slug='recovery'),'روز استراحت هم بخشی از برنامه است','وقتی در برنامه «استراحت» می‌بینی، یک جلسه را از دست نداده‌ای؛ داری بخشی از همان برنامه را انجام می‌دهی. تقویم کامل، لزوماً تقویمی با هفت جلسه سنگین نی','وقتی در برنامه «استراحت» می‌بینی، یک جلسه را از دست نداده‌ای؛ داری بخشی از همان برنامه را انجام می‌دهی. تقویم کامل، لزوماً تقویمی با هفت جلسه سنگین نیست.','🍃',1,'[{"type": "p", "text": "وقتی در برنامه «استراحت» می‌بینی، یک جلسه را از دست نداده‌ای؛ داری بخشی از همان برنامه را انجام می‌دهی. تقویم کامل، لزوماً تقویمی با هفت جلسه سنگین نیست."}, {"type": "h2", "text": "برای روز استراحت قرار مشخص بگذار"}, {"type": "p", "text": "در برنامه‌ساز مربی، روز استراحت از روز تمرین جداست. اگر می‌خواهی فعالیت سبکی داشته باشی، آن را با شرایطت و نظر مربی هماهنگ کن. فعالیت روزمره هم بخشی از تحرک است؛ لازم نیست هر حرکت را به یک چالش ورزشی تبدیل کنی."}, {"type": "h2", "text": "گزارش واقعی از عدد کامل بهتر است"}, {"type": "list", "items": ["اگر یک جلسه را انجام ندادی، آن را به‌عنوان تمرین کامل ثبت نکن.", "اگر خستگی یا درد غیرمعمول داری، به مربی توضیح بده.", "برای جبران جلسه ازدست‌رفته، چند جلسه را بدون برنامه در یک روز جمع نکن."]}, {"type": "h2", "text": "آخر هفته فقط تعداد جلسه را نبین"}, {"type": "p", "text": "به پیوستگی برنامه، زمان در دسترس و کیفیت ثبت‌ها هم نگاه کن. شاید برنامه مناسب تو با جلسه کمتر، قابل‌اجراتر باشد. تغییر روزهای تمرین و استراحت را آگاهانه انجام بده تا برنامه‌ای که در اپ می‌بینی با زندگی واقعی تو هماهنگ بماند."}]',NULL,now(),now(),1,'انتشار اولیه') ON CONFLICT (slug) DO NOTHING;
INSERT INTO esifit."ArticleSource" (id,"articleId",title,publisher,url,"sourceType") VALUES ('editorial_s_716a38480ad79444b6c5568ad43b43b9',(SELECT id FROM esifit."Article" WHERE slug='rest-day-without-guilt'),'فعالیت بدنی و توصیه‌های عمومی','سازمان جهانی بهداشت','https://www.who.int/news-room/fact-sheets/detail/physical-activity','organization') ON CONFLICT (id) DO NOTHING;
INSERT INTO esifit."Article" ("id","slug","title","contentType","status","authorId","categoryId","metaTitle","metaDescription","excerpt","coverEmoji","readingMinutes","contentBlocks","calculatorSlug","publishedAt","updatedAt","revision","revisionNote") VALUES ('editorial_a_bb0dd6ea2e9fa908fa8f414b28bb174f','bmi-meaning-and-limits','BMI چه می‌گوید و چه چیزهایی را نمی‌گوید؟','guide','published','esifit-editorial',(SELECT id FROM esifit."Category" WHERE slug='science'),'BMI چه می‌گوید و چه چیزهایی را نمی‌گوید؟','BMI رابطه وزن و قد را در یک عدد خلاصه می‌کند؛ اما تمام داستان ترکیب بدن و سلامت تو نیست. از آن به‌عنوان یک نشانه اولیه استفاده کن، نه حکم نهایی.','BMI رابطه وزن و قد را در یک عدد خلاصه می‌کند؛ اما تمام داستان ترکیب بدن و سلامت تو نیست. از آن به‌عنوان یک نشانه اولیه استفاده کن، نه حکم نهایی.','🔎',1,'[{"type": "p", "text": "BMI رابطه وزن و قد را در یک عدد خلاصه می‌کند؛ اما تمام داستان ترکیب بدن و سلامت تو نیست. از آن به‌عنوان یک نشانه اولیه استفاده کن، نه حکم نهایی."}, {"type": "h2", "text": "فرمول ساده است"}, {"type": "p", "text": "وزن بر حسب کیلوگرم بر مجذور قد بر حسب متر تقسیم می‌شود. مثلاً برای قد ۱٫۷۵ متر، وزن بر ۱٫۷۵ × ۱٫۷۵ تقسیم می‌شود. ماشین‌حساب اسی‌فیت همین محاسبه را سریع انجام می‌دهد و برای استفاده پایه به ثبت‌نام نیاز ندارد."}, {"type": "h2", "text": "چرا نتیجه همیشه کافی نیست؟"}, {"type": "p", "text": "طبق توضیح NIDDK، BMI چربی بدن را مستقیم اندازه نمی‌گیرد. فرد عضلانی ممکن است بدون چربی زیاد، BMI بالاتری داشته باشد. شرایط فردی و اندازه‌های دیگر هم در ارزیابی سلامت نقش دارند."}, {"type": "h2", "text": "نتیجه را چطور به کار ببریم؟"}, {"type": "list", "items": ["قد و وزن را با واحد درست وارد کن.", "نتیجه را با درصد چربی بدن یا تشخیص بیماری اشتباه نگیر.", "برای تصمیم درمانی، فقط به رنگ یا محدوده یک ماشین‌حساب تکیه نکن."]}, {"type": "callout", "title": "عدد خودت را حساب کن", "text": "ماشین‌حساب اسی‌فیت نقطه شروعی برای بررسی این عدد است؛ نتیجه را کنار شرایط و هدف خودت بخوان."}]','bmi',now(),now(),1,'انتشار اولیه') ON CONFLICT (slug) DO NOTHING;
INSERT INTO esifit."ArticleSource" (id,"articleId",title,publisher,url,"sourceType") VALUES ('editorial_s_caa134f3f7d5b42bd90548fa99532871',(SELECT id FROM esifit."Article" WHERE slug='bmi-meaning-and-limits'),'آیا وزن من در محدوده مناسب است؟','NIDDK','https://www.niddk.nih.gov/health-information/weight-management/adult-overweight-obesity/am-i-healthy-weight','organization') ON CONFLICT (id) DO NOTHING;
INSERT INTO esifit."Article" ("id","slug","title","contentType","status","authorId","categoryId","metaTitle","metaDescription","excerpt","coverEmoji","readingMinutes","contentBlocks","calculatorSlug","publishedAt","updatedAt","revision","revisionNote") VALUES ('editorial_a_fae52dc130b09d1bb82149f5c136b3b5','numbers-are-estimates','چرا عددهای تغذیه و ماشین‌حساب‌ها تخمینی‌اند؟','guide','published','esifit-editorial',(SELECT id FROM esifit."Category" WHERE slug='science'),'چرا عددهای تغذیه و ماشین‌حساب‌ها تخمینی‌اند؟','عدد دقیق روی صفحه، الزاماً به معنای اندازه‌گیری دقیق بدن تو نیست. شناختن ورودی و محدودیت هر ابزار کمک می‌کند از آن انتظار درستی داشته باشی.','عدد دقیق روی صفحه، الزاماً به معنای اندازه‌گیری دقیق بدن تو نیست. شناختن ورودی و محدودیت هر ابزار کمک می‌کند از آن انتظار درستی داشته باشی.','📊',1,'[{"type": "p", "text": "عدد دقیق روی صفحه، الزاماً به معنای اندازه‌گیری دقیق بدن تو نیست. شناختن ورودی و محدودیت هر ابزار کمک می‌کند از آن انتظار درستی داشته باشی."}, {"type": "h2", "text": "بین داده مرجع و غذای بشقاب فرق هست"}, {"type": "p", "text": "پایگاه غذایی، مقدار مواد مغذی یک نمونه یا دستور مشخص را گزارش می‌کند. نوع ماده اولیه، روش پخت و مقدار سهم می‌تواند با غذای واقعی تو فرق داشته باشد. به همین دلیل برچسب منبع و مقدار سهم را کنار عدد کالری بخوان."}, {"type": "h2", "text": "ورودی ثابت، مقایسه روشن‌تر"}, {"type": "p", "text": "اگر یک روز وزن خام و روز دیگر وزن پخته را وارد کنی، تفاوت گزارش ممکن است از روش ثبت باشد. برای مقایسه روزها، واحد و حالت غذا را ثابت انتخاب کن. تخمین قابل تکرار، از عددی ظاهراً دقیق با ورودی نامشخص مفیدتر است."}, {"type": "h2", "text": "در اسی‌فیت از کجا شروع کنیم؟"}, {"type": "list", "items": ["اول واحد و مقدار سهم غذای انتخاب‌شده را بررسی کن.", "نتیجه ماشین‌حساب را نقطه شروع بدان و تغییرات را با مربی مرور کن.", "ثبت‌نشدن وعده به معنای غذا نخوردن نیست؛ گزارش ناقص را مصرف صفر تعبیر نکن."]}]',NULL,now(),now(),1,'انتشار اولیه') ON CONFLICT (slug) DO NOTHING;
INSERT INTO esifit."ArticleSource" (id,"articleId",title,publisher,url,"sourceType") VALUES ('editorial_s_a97fe6b470835f5f2ff4df96c2cb44d2',(SELECT id FROM esifit."Article" WHERE slug='numbers-are-estimates'),'FoodData Central: راهنمای داده‌های غذایی','USDA','https://fdc.nal.usda.gov/data-documentation.html','organization') ON CONFLICT (id) DO NOTHING;
